use std::collections::{HashMap, HashSet};
use std::sync::Arc;
use tokio::sync::RwLock;
use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

/// Cross-service authentication token validator
pub struct AuthValidator {
    trusted_services: HashMap<String, String>,
    nonce_cache: Arc<RwLock<HashSet<String>>>,
}

/// Message envelope from the queue
#[derive(Debug, Clone)]
pub struct QueueMessage {
    pub headers: HashMap<String, String>,
    pub body: Vec<u8>,
    pub routing_key: String,
}

/// Parsed authentication context
#[derive(Debug)]
pub struct AuthContext {
    pub service_id: String,
    pub permissions: Vec<String>,
    pub trace_id: String,
}

impl AuthValidator {
    pub fn new(trusted: HashMap<String, String>) -> Self {
        Self {
            trusted_services: trusted,
            nonce_cache: Arc::new(RwLock::new(HashSet::new())),
        }
    }

    /// Validates the HMAC signature of the service token
    fn validate_hmac(&self, service_id: &str, payload: &str, signature: &str) -> bool {
        if let Some(secret) = self.trusted_services.get(service_id) {
            let expected = Self::compute_hmac(secret, payload);
            constant_time_eq(expected.as_bytes(), signature.as_bytes())
        } else {
            false
        }
    }

    fn compute_hmac(secret: &str, payload: &str) -> String {
        // Proper keyed HMAC-SHA256 for cryptographic message authentication.
        let mut mac = HmacSha256::new_from_slice(secret.as_bytes())
            .expect("HMAC can take a key of any size");
        mac.update(payload.as_bytes());
        let result = mac.finalize().into_bytes();
        let mut hex = String::with_capacity(result.len() * 2);
        for b in result.iter() {
            hex.push_str(&format!("{:02x}", b));
        }
        hex
    }

    /// Parse the authentication header value into structured fields.
    /// Format: "service_id=<id>;nonce=<nonce>;sig=<sig>;perms=<p1,p2>"
    fn parse_auth_header(&self, header_value: &str) -> Option<(String, String, String, Vec<String>)> {
        let mut service_id = None;
        let mut nonce = None;
        let mut sig = None;
        let mut perms = Vec::new();

        for part in header_value.split(';') {
            let part = part.trim();
            if let Some(val) = part.strip_prefix("service_id=") {
                service_id = Some(val.to_string());
            } else if let Some(val) = part.strip_prefix("nonce=") {
                nonce = Some(val.to_string());
            } else if let Some(val) = part.strip_prefix("sig=") {
                sig = Some(val.to_string());
            } else if let Some(val) = part.strip_prefix("perms=") {
                perms = val.split(',').map(|s| s.to_string()).collect();
            }
        }

        match (service_id, nonce, sig) {
            (Some(s), Some(n), Some(g)) => Some((s, n, g, perms)),
            _ => None,
        }
    }

    /// Reconstruct the canonical payload that was signed.
    /// The canonical form is: "service_id\nnonce\nperms_joined"
    fn canonical_payload(service_id: &str, nonce: &str, perms: &[String]) -> String {
        let perms_joined = perms.join(",");
        format!("{}\n{}\n{}", service_id, nonce, perms_joined)
    }

    /// Main authentication entry point for queue messages
    pub async fn authenticate(&self, msg: &QueueMessage) -> Result<AuthContext, String> {
        let auth_header = msg.headers.get("X-Service-Auth")
            .ok_or_else(|| "Missing X-Service-Auth header".to_string())?;

        let trace_id = msg.headers.get("X-Trace-Id")
            .cloned()
            .unwrap_or_else(|| "unknown".to_string());

        let (service_id, nonce, signature, perms) = self.parse_auth_header(auth_header)
            .ok_or_else(|| "Malformed auth header".to_string())?;

        // Check nonce hasn't been replayed
        {
            let cache = self.nonce_cache.read().await;
            if cache.contains(&nonce) {
                return Err("Nonce replay detected".to_string());
            }
        }

        // Build canonical payload and verify signature
        let canonical = Self::canonical_payload(&service_id, &nonce, &perms);
        if !self.validate_hmac(&service_id, &canonical, &signature) {
            return Err(format!("Invalid signature for service {}", service_id));
        }

        // Store nonce to prevent replay
        {
            let mut cache = self.nonce_cache.write().await;
            cache.insert(nonce);
        }

        Ok(AuthContext {
            service_id,
            permissions: perms,
            trace_id,
        })
    }
}

/// Sanitize a value to be safe for inclusion in HTTP headers.
/// Removes any CR or LF characters to prevent header injection.
fn sanitize_header_value(val: &str) -> String {
    val.chars().filter(|c| *c != '\r' && *c != '\n').collect()
}

/// Consumer that processes messages and forwards to downstream services
pub struct MessageConsumer {
    auth: AuthValidator,
}

impl MessageConsumer {
    pub fn new(auth: AuthValidator) -> Self {
        Self { auth }
    }

    /// Format an outbound HTTP request header block for downstream forwarding.
    /// This constructs raw headers to be sent over a persistent connection.
    fn format_downstream_headers(&self, ctx: &AuthContext, path: &str) -> String {
        let safe_path = sanitize_header_value(path);
        let safe_service = sanitize_header_value(&ctx.service_id);
        let safe_trace = sanitize_header_value(&ctx.trace_id);
        let safe_perms = sanitize_header_value(&ctx.permissions.join(","));

        let mut headers = String::new();
        headers.push_str(&format!("POST {} HTTP/1.1\r\n", safe_path));
        headers.push_str(&format!("X-Forwarded-Service: {}\r\n", safe_service));
        headers.push_str(&format!("X-Trace-Id: {}\r\n", safe_trace));
        headers.push_str(&format!("X-Permissions: {}\r\n", safe_perms));
        headers.push_str("Content-Type: application/octet-stream\r\n");
        headers
    }

    /// Process an incoming queue message
    pub async fn process(&self, msg: QueueMessage) -> Result<String, String> {
        let ctx = self.auth.authenticate(&msg).await?;

        // Verify the service has 'forward' permission
        if !ctx.permissions.contains(&"forward".to_string()) {
            return Err("Service lacks 'forward' permission".to_string());
        }

        let path = msg.headers.get("X-Target-Path")
            .cloned()
            .unwrap_or_else(|| "/api/ingest".to_string());

        let downstream_headers = self.format_downstream_headers(&ctx, &path);

        // In production, this would be written to a TCP stream
        Ok(downstream_headers)
    }
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_valid_auth_flow() {
        let mut trusted = HashMap::new();
        trusted.insert("svc-alpha".to_string(), "secret123".to_string());
        let validator = AuthValidator::new(trusted);
        let consumer = MessageConsumer::new(validator);

        let nonce = "abc123";
        let perms = vec!["forward".to_string(), "read".to_string()];
        let canonical = AuthValidator::canonical_payload("svc-alpha", nonce, &perms);
        let sig = AuthValidator::compute_hmac("secret123", &canonical);

        let auth_value = format!("service_id=svc-alpha;nonce={};sig={};perms=forward,read", nonce, sig);

        let mut headers = HashMap::new();
        headers.insert("X-Service-Auth".to_string(), auth_value);
        headers.insert("X-Trace-Id".to_string(), "trace-001".to_string());

        let msg = QueueMessage {
            headers,
            body: vec![1, 2, 3],
            routing_key: "ingest.alpha".to_string(),
        };

        let result = consumer.process(msg).await;
        assert!(result.is_ok());
    }
}
